import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Codex CLI","description":"Connect Codex CLI to the Tokeness Responses API through CC Switch or manual configuration.","frontmatter":{"title":"Codex CLI","description":"Connect Codex CLI to the Tokeness Responses API through CC Switch or manual configuration."},"headers":[],"relativePath":"integrations/codex-cli.md","filePath":"integrations/codex-cli.md","lastUpdated":1783700215000}'),o={name:"integrations/codex-cli.md"};function n(l,e,d,h,r,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="codex-cli" tabindex="-1">Codex CLI <a class="header-anchor" href="#codex-cli" aria-label="Permalink to &quot;Codex CLI&quot;">​</a></h1><p>Codex CLI can use a custom model provider. Tokeness connects via the OpenAI Responses protocol — the Base URL is always:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://n.tokeness.io/v1</span></span></code></pre></div><p>If you use <a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">CC Switch</a>, it writes Codex&#39;s <code>auth.json</code> and <code>config.toml</code> for you. If you need to check the configuration manually, this page also provides file examples.</p><h2 id="connection-details" tabindex="-1">Connection details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Provider Name</td><td><code>Tokeness</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model</td><td>Copied from the Tokeness model marketplace</td></tr><tr><td>Wire API</td><td><code>responses</code></td></tr></tbody></table><h2 id="_1-prepare-tokeness" tabindex="-1">1. Prepare Tokeness <a class="header-anchor" href="#_1-prepare-tokeness" aria-label="Permalink to &quot;1. Prepare Tokeness&quot;">​</a></h2><p>Prepare three things first:</p><ol><li>A Tokeness API key.</li><li>A Tokeness model name.</li><li>Available balance.</li></ol><p>Create a separate key for Codex:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>codex-cli-local</span></span></code></pre></div><p>If you later notice abnormal Codex consumption, you can disable just this key without affecting other tools.</p><h2 id="_2-install-codex-cli" tabindex="-1">2. Install Codex CLI <a class="header-anchor" href="#_2-install-codex-cli" aria-label="Permalink to &quot;2. Install Codex CLI&quot;">​</a></h2><p>Confirm Node.js is available:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @openai/codex</span></span></code></pre></div><p>If npm downloads are slow:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @openai/codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry=https://registry.npmmirror.com</span></span></code></pre></div><p>Confirm the command is available:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="_3-configure-through-cc-switch" tabindex="-1">3. Configure through CC Switch <a class="header-anchor" href="#_3-configure-through-cc-switch" aria-label="Permalink to &quot;3. Configure through CC Switch&quot;">​</a></h2><ol><li>Open CC Switch.</li><li>Switch to <code>Codex</code> on the left.</li><li>Click the <code>+</code> button in the top right.</li><li>If there is no Tokeness preset, choose a custom provider.</li><li>Set the name to <code>Tokeness</code>.</li><li>Enter your Tokeness API key.</li><li>Set the Base URL to <code>https://n.tokeness.io/v1</code>.</li><li>Enter the full model name from the Tokeness model marketplace.</li><li>For API type or Wire API, select <code>responses</code>.</li><li>Save and enable.</li></ol><p>After switching, close the current terminal, reopen one, and then run Codex. Codex CLI usually reads its configuration at startup, so the old terminal may still hold the previous environment.</p><h2 id="_4-manual-configuration-reference" tabindex="-1">4. Manual configuration reference <a class="header-anchor" href="#_4-manual-configuration-reference" aria-label="Permalink to &quot;4. Manual configuration reference&quot;">​</a></h2><p>If you want to verify what CC Switch wrote, you can check the Codex configuration directory.</p><p>macOS / Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.codex</span></span></code></pre></div><p>Windows PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ChildItem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">USERPROFILE\\.codex</span></span></code></pre></div><p><code>auth.json</code> example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;OPENAI_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your Tokeness API key&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>config.toml</code> example:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tokeness&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;the model name copied from the Tokeness model marketplace&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">disable_response_storage = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">model_providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tokeness</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tokeness&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://n.tokeness.io/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wire_api = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;responses&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">requires_openai_auth = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Field descriptions:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>model_provider</code></td><td>The currently active provider</td></tr><tr><td><code>model</code></td><td>The model Codex uses by default</td></tr><tr><td><code>base_url</code></td><td>Tokeness endpoint address</td></tr><tr><td><code>wire_api</code></td><td>Codex uses the Responses protocol</td></tr><tr><td><code>requires_openai_auth</code></td><td>Uses OpenAI-style Bearer key authentication</td></tr></tbody></table><p>If you manage Codex through CC Switch, do not manually edit these two files long-term. The next time you switch providers in CC Switch, your manual changes may be overwritten.</p><h2 id="_5-verification" tabindex="-1">5. Verification <a class="header-anchor" href="#_5-verification" aria-label="Permalink to &quot;5. Verification&quot;">​</a></h2><p>Reopen the terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span></span></code></pre></div><p>Enter:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please reply with a single sentence confirming Codex is now connected to Tokeness.</span></span></code></pre></div><p>Then check the Tokeness usage logs to confirm:</p><ul><li>A new request appeared.</li><li>The key is the Codex-dedicated key.</li><li>The model name is correct.</li><li>The status code is successful.</li></ul><h2 id="_6-multi-model-configuration" tabindex="-1">6. Multi-model configuration <a class="header-anchor" href="#_6-multi-model-configuration" aria-label="Permalink to &quot;6. Multi-model configuration&quot;">​</a></h2><p>You can create multiple Codex providers in CC Switch, or switch the <code>model</code> in the configuration.</p><table tabindex="0"><thead><tr><th>Configuration name</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Tokeness Codex Coding</code></td><td>Daily code modifications</td></tr><tr><td><code>Tokeness Codex Reasoning</code></td><td>Complex analysis, solution design</td></tr><tr><td><code>Tokeness Codex Docs</code></td><td>Document cleanup, bulk rewriting</td></tr></tbody></table><p>After switching, reopen the terminal.</p><h2 id="_7-troubleshooting" tabindex="-1">7. Troubleshooting <a class="header-anchor" href="#_7-troubleshooting" aria-label="Permalink to &quot;7. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td><code>codex</code> command not found</td><td>Reinstall, or restart the terminal</td></tr><tr><td>Still using the old model</td><td>Close the terminal and reopen; check <code>model_provider</code></td></tr><tr><td>401 Unauthorized</td><td>Check the key in <code>auth.json</code></td></tr><tr><td>404 Not Found</td><td>Check that <code>base_url</code> is <code>https://n.tokeness.io/v1</code></td></tr><tr><td>Responses-related errors</td><td>Check that <code>wire_api = &quot;responses&quot;</code></td></tr><tr><td>model not found</td><td>Re-copy the model name from the Tokeness model marketplace</td></tr><tr><td>No Tokeness logs</td><td>Codex is not using the Tokeness configuration; check whether the provider is enabled</td></tr></tbody></table>`,50)])])}const u=t(o,[["render",n]]);export{k as __pageData,u as default};
